            "type": "STRING"
          }
        },
        "required": [
          "text"
        ]
      }
    },
    "attention": {
      "type": "ARRAY",
      "items": {
        "type": "OBJECT",
        "properties": {
          "itemId": {
            "type": "STRING"
          },
          "why": {
            "type": "STRING"
          },
          "action": {
            "type": "STRING"
          }
        },
        "required": [
          "itemId",
          "why",
          "action"
        ]
      }
    },
    "blocked": {
      "type": "ARRAY",
      "items": {
