          "suggestion": {
            "type": "STRING"
          }
        },
        "required": [
          "personId",
          "blockedOn",
          "suggestion"
        ]
      }
    }
  },
  "required": [
    "headline",
    "topWork",
    "happened",
    "attention",
    "blocked"
  ]
};
const SAMPLE_SNAPSHOT = {
