const body = $('Digest request').first().json.body || {};
const snapshot = Array.isArray(body.openItems) && body.openItems.length ? body : SAMPLE_SNAPSHOT;
const config = $('Config').first().json;

return [
  {
    json: {
      model: config.model,
      fallbackModel: config.fallbackModel,
      usedSample: snapshot === SAMPLE_SNAPSHOT,
      snapshot,
      request: {
        systemInstruction: { parts: [{ text: SYSTEM_PROMPT }] },
        contents: [{ role: 'user', parts: [{ text: 'Snapshot:\n' + JSON.stringify(snapshot) }] }],
        generationConfig: { temperature: 0.3, responseMimeType: 'application/json', responseSchema: RESPONSE_SCHEMA },
      },
    },
  },
];

// n8n Code node · "Validate brief" (Run once for all items)
// Parses Gemini's JSON, drops anything that doesn't point at a real item or person,
// and shapes the response the WorkRadar app expects: { brief, engine, model }.

const req = $('Build Gemini request').first().json;
const res = $input.first().json;
const parts = (res.candidates && res.candidates[0] && res.candidates[0].content && res.candidates[0].content.parts) || [];
const text = parts.filter((p) => !p.thought && p.text).map((p) => p.text).join('');

let brief;
try {
  brief = JSON.parse(text);
} catch (e) {
  throw new Error('Gemini did not return valid JSON: ' + text.slice(0, 200));
}

const ids = new Set(req.snapshot.openItems.map((i) => i.id).concat((req.snapshot.happenedToday || []).map((h) => h.itemId).filter(Boolean)));
const people = new Set((req.snapshot.team || []).map((p) => p.id));
const str = (v) => (typeof v === 'string' ? v.trim() : '');
const list = (v) => (Array.isArray(v) ? v : []);

const clean = {
  headline: str(brief.headline),
  topWork: list(brief.topWork).filter((x) => ids.has(x.itemId) && str(x.why)).slice(0, 3),
  happened: list(brief.happened).filter((x) => str(x.text)).slice(0, 6),
  attention: list(brief.attention).filter((x) => ids.has(x.itemId) && str(x.why)).slice(0, 6),
  blocked: list(brief.blocked).filter((x) => (people.size === 0 || people.has(x.personId)) && str(x.blockedOn)),
};
if (!clean.headline) throw new Error('Gemini response had no headline');

return [{ json: { brief: clean, engine: 'n8n', model: req.model, usedSample: req.usedSample, generatedAt: new Date().toISOString() } }];

// n8n Code node · "Rule-based fallback" (Run once for all items)
// Runs when the Gemini call fails (no credential, quota, network). Builds the same
// brief shape from the ranked snapshot so the app always gets an answer.

const req = $('Build Gemini request').first().json;
const s = req.snapshot;
const open = s.openItems || [];
const now = open.filter((i) => i.ring === 'now');
const blocked = s.blockedPeople || [];
const onYou = blocked.filter((b) => b.blockedByManager).length;
const first = (name) => String(name || '').split(' ')[0];

let headline = now.length
  ? `${now.length} ${now.length === 1 ? 'item needs' : 'items need'} your attention`
  : 'Nothing needs you urgently right now';
headline += blocked.length ? `, and ${blocked.length} ${blocked.length === 1 ? 'person is' : 'people are'} blocked${onYou ? ` (${onYou} on you)` : ''}.` : '.';
if (open[0] && open[0].ring === 'now') headline += ` Start with ${open[0].ref}: ${String(open[0].why).split('. ')[0]}.`;

const brief = {
  headline,
  topWork: open.slice(0, 3).map((i) => ({ itemId: i.id, why: i.suggestedNextStep || i.why })),
  happened: (s.happenedToday || []).slice(0, 6),
  attention: now.slice(0, 6).map((i) => ({ itemId: i.id, why: i.why, action: i.suggestedNextStep || 'Open it and decide the next step.' })),
  blocked: blocked.map((b) => ({
    personId: b.personId,
    itemId: b.itemId,
    blockedOn: b.blockedOn,
    since: b.blockedFor,
    suggestion: b.blockedByManager ? `Unblock ${first(b.person)} by acting on ${b.ref} yourself.` : `Check what ${first(b.person)} needs to move ${b.ref}.`,
  })),
};

const err = $input.first().json.error;
return [{ json: { brief, engine: 'n8n', model: 'rule-based fallback', fallbackReason: err ? String(err.message || err) : 'Gemini unavailable', generatedAt: new Date().toISOString() } }];
